// dropos-buildfix2.js
const fs=require('fs'),path=require('path'),{execSync}=require('child_process');
const files={"backend/prisma/schema.prisma":"// prisma/schema.prisma\n// DropOS - Full Multi-Tenant SaaS Schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─── Enums ───────────────────────────────────────────────────────────────────\n\nenum Role {\n  SUPER_ADMIN\n  STORE_OWNER\n  CUSTOMER\n}\n\nenum UserStatus {\n  ACTIVE\n  SUSPENDED\n  PENDING_VERIFICATION\n  BANNED\n}\n\nenum PlanType {\n  STARTER\n  PRO\n  ADVANCED\n}\n\nenum StoreStatus {\n  ACTIVE\n  SUSPENDED\n  PENDING\n  ARCHIVED\n}\n\nenum ProductStatus {\n  ACTIVE\n  DRAFT\n  OUT_OF_STOCK\n  ARCHIVED\n}\n\nenum OrderStatus {\n  PENDING\n  PROCESSING\n  SHIPPED\n  DELIVERED\n  COMPLETED\n  CANCELLED\n  REFUNDED\n}\n\nenum PaymentStatus {\n  PENDING\n  SUCCESS\n  FAILED\n  REFUNDED\n  DISPUTED\n}\n\nenum PaymentGateway {\n  STRIPE\n  PAYSTACK\n  FLUTTERWAVE\n}\n\nenum SubscriptionStatus {\n  ACTIVE\n  CANCELLED\n  EXPIRED\n  PAST_DUE\n}\n\nenum SupportStatus {\n  OPEN\n  IN_PROGRESS\n  RESOLVED\n  CLOSED\n}\n\nenum Priority {\n  LOW\n  MEDIUM\n  HIGH\n  URGENT\n}\n\nenum LogLevel {\n  INFO\n  WARN\n  ERROR\n  CRITICAL\n}\n\n// ─── User ────────────────────────────────────────────────────────────────────\n\nmodel User {\n  id                String     @id @default(uuid())\n  email             String     @unique\n  password          String\n  name              String\n  phone             String?\n  avatar            String?\n  role              Role       @default(STORE_OWNER)\n  status            UserStatus @default(PENDING_VERIFICATION)\n  emailVerified     Boolean    @default(false)\n  emailVerifyToken  String?\n  passwordResetToken String?\n  passwordResetExpiry DateTime?\n  twoFAEnabled      Boolean    @default(false)\n  twoFASecret       String?\n  lastLogin         DateTime?\n  loginAttempts     Int        @default(0)\n  lockedUntil       DateTime?\n  refreshToken      String?\n  adminNotes        String?\n  flags             String[]   @default([])\n  onboarded         Boolean    @default(false)\n  onboardNiche      String?\n  onboardStage      String?\n  onboardGoal       String?\n  onboardTemplate   String?\n  country           String?\n  city              String?\n  timezone          String?    @default(\"UTC\")\n  createdAt         DateTime   @default(now())\n  updatedAt         DateTime   @updatedAt\n\n  // Relations\n  stores            Store[]\n  kaiConversations  KaiConversation[]\n  subscription      Subscription?\n  supportTickets    SupportTicket[]\n  notifications     Notification[]\n  auditLogs         AuditLog[]\n  pushSubscriptions PushSubscription[]\n  referral          Referral?\n  refreshTokens     RefreshToken[]\n\n  @@index([email])\n  @@index([role])\n  @@index([status])\n  @@map(\"users\")\n}\n\n// ─── Store ───────────────────────────────────────────────────────────────────\n\nmodel Store {\n  id              String      @id @default(uuid())\n  ownerId         String\n  name            String\n  slug            String      @unique\n  description     String?\n  logo            String?\n  banner          String?\n  domain          String?     @unique\n  customDomain    String?     @unique\n  templateId      String?\n  paystackConnected Boolean  @default(false)\n  status          StoreStatus @default(PENDING)\n  primaryColor    String?     @default(\"#7c3aed\")\n  accentColor     String?     @default(\"#a855f7\")\n  theme           String?     @default(\"default\")\n  secondaryColor  String?\n  fontFamily      String?     @default(\"DM Sans\")\n  borderRadius    String?     @default(\"rounded\")\n  tagline         String?\n  showReviews     Boolean     @default(true)\n  showInventory   Boolean     @default(true)\n  productsPerRow  Int         @default(4)\n  currency        String      @default(\"USD\")\n  country         String?\n  address         String?\n  supportEmail    String?\n  supportPhone    String?\n  taxRate         Float?      @default(0)\n  shippingEnabled Boolean     @default(true)\n  freeShippingMin Float?\n  metaTitle         String?\n  metaDescription   String?\n  // ── SMS / WhatsApp via Twilio ─────────────────────────────────────────────\n  suppliers           Supplier[]\n  fulfillmentOrders   FulfillmentOrder[]\n\n  // ── Multi-currency ───────────────────────────────────────────────────────────\n  supportedCurrencies Json?       // e.g. [\"USD\",\"EUR\",\"GBP\",\"NGN\"]\n  autoDetectCurrency  Boolean     @default(true)\n  smsEnabled        Boolean     @default(false)\n  smsPhone          String?     // owner's phone for incoming alerts  e.g. +2348012345678\n  whatsappEnabled   Boolean     @default(false)\n  whatsappPhone     String?     // owner's WhatsApp number\n  // ── Live Chat widget ────────────────────────────────────────────────────────\n  liveChatProvider  String?     // \"tawk\", \"crisp\", \"tidio\", \"whatsapp\", or null\n  liveChatId        String?     // Tawk.to property ID / Crisp website ID / Tidio key\n  liveChatEnabled   Boolean     @default(false)\n  notifyOwnerSms    Boolean     @default(true)   // SMS owner on new order\n  notifyCustomerSms Boolean     @default(false)\n  loyaltyEnabled    Boolean     @default(false)\n  themeSettings     Json?  // SMS customer on order + status\n  createdAt         DateTime    @default(now())\n  updatedAt       DateTime    @updatedAt\n\n  // Relations\n  owner           User        @relation(fields: [ownerId], references: [id], onDelete: Cascade)\n  products        Product[]\n  orders          Order[]\n  customers       StoreCustomer[]\n  payments        Payment[]\n  analytics       Analytics[]\n  shippingZones   ShippingZone[]\n  coupons         Coupon[]\n  reviews         Review[]\n  abandonedCarts  AbandonedCart[]\n\n  discounts       Discount[]\n  refunds         Refund[]\n  giftCards       GiftCard[]\n  webhooks        StoreWebhook[]\n  flashSales      FlashSale[]\n  backups         StoreBackup[]\n  apiKeys         ApiKey[]\n  returnRequests  ReturnRequest[]\n  affiliates      Affiliate[]\n  bundles         Bundle[]\n  groupBuys       GroupBuy[]\n  milestones      Milestone[]\n  @@index([ownerId])\n  @@index([slug])\n  @@index([status])\n  @@map(\"stores\")\n  integrations    StoreIntegration[]\n}\n\n// ─── Product ─────────────────────────────────────────────────────────────────\n\nmodel Product {\n  id              String        @id @default(uuid())\n  storeId         String\n  name            String\n  slug            String\n  description     String?\n  price           Float\n  comparePrice    Float?\n  costPrice       Float?\n  sku             String?\n  barcode         String?\n  weight          Float?\n  inventory       Int           @default(0)\n  trackInventory  Boolean       @default(true)\n  allowBackorder  Boolean       @default(false)\n  images          String[]      @default([])\n  category        String?\n  tags            String[]      @default([])\n  status          ProductStatus @default(DRAFT)\n  isDigital       Boolean       @default(false)\n  sourceUrl       String?\n  stockQuantity   Int?\n  metaTitle       String?\n  metaDescription String?\n  createdAt       DateTime      @default(now())\n  updatedAt       DateTime      @updatedAt\n\n  // Relations\n  store           Store         @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  variants        ProductVariant[]\n  orderItems      OrderItem[]\n  reviews         Review[]\n  supplierProducts SupplierProduct[]\n  groupBuys       GroupBuy[]\n\n  @@unique([storeId, slug])\n  @@index([storeId])\n  @@index([status])\n  @@map(\"products\")\n}\n\nmodel ProductVariant {\n  id          String   @id @default(uuid())\n  productId   String\n  name        String\n  value       String\n  price       Float?\n  inventory   Int      @default(0)\n  sku         String?\n  image       String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  product     Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@index([productId])\n  @@map(\"product_variants\")\n}\n\n// ─── Store Customer ──────────────────────────────────────────────────────────\n\nmodel StoreCustomer {\n  id              String    @id @default(uuid())\n  storeId         String\n  email           String\n  name            String\n  phone           String?\n  address         Json?\n  emailVerified   Boolean   @default(false)\n  totalSpent      Float     @default(0)\n  orderCount      Int       @default(0)\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  store           Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  orders          Order[]\n\n  @@unique([storeId, email])\n  @@index([storeId])\n  @@map(\"store_customers\")\n}\n\n// ─── Order ───────────────────────────────────────────────────────────────────\n\nmodel Order {\n  id                String      @id @default(uuid())\n  orderNumber       String      @unique\n  storeId           String\n  customerId        String?\n  customerEmail     String\n  customerName      String\n  customerPhone     String?\n  shippingAddress   Json?\n  billingAddress    Json?\n  status            OrderStatus @default(PENDING)\n  subtotal          Float\n  shippingCost      Float       @default(0)\n  taxAmount         Float       @default(0)\n  discountAmount    Float       @default(0)\n  total             Float\n  currency          String      @default(\"USD\")\n  notes             String?\n  trackingNumber    String?\n  trackingUrl       String?\n  refundAmount      Float?\n  cancelReason      String?\n  fulfillmentStatus String      @default(\"UNFULFILLED\")\n  tax               Float       @default(0)\n  createdAt         DateTime    @default(now())\n  updatedAt         DateTime    @updatedAt\n\n  store             Store         @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  customer          StoreCustomer? @relation(fields: [customerId], references: [id])\n  items             OrderItem[]\n  payment           Payment?\n  refunds           Refund[]\n  returns           ReturnRequest[]\n\n  @@index([storeId])\n  @@index([status])\n  @@index([orderNumber])\n  @@map(\"orders\")\n}\n\nmodel OrderItem {\n  id          String   @id @default(uuid())\n  orderId     String\n  productId   String\n  variantId   String?\n  name        String\n  sku         String?\n  price       Float\n  quantity    Int\n  total       Float\n  image       String?\n  createdAt   DateTime @default(now())\n\n  order       Order    @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  product     Product  @relation(fields: [productId], references: [id])\n\n  @@index([orderId])\n  @@map(\"order_items\")\n}\n\n// ─── Payment ─────────────────────────────────────────────────────────────────\n\nmodel Payment {\n  id                String         @id @default(uuid())\n  orderId           String         @unique\n  storeId           String\n  gateway           PaymentGateway\n  gatewayReference  String?\n  gatewayResponse   Json?\n  amount            Float\n  currency          String         @default(\"USD\")\n  platformFee       Float\n  platformFeePercent Float\n  storeEarnings     Float\n  status            PaymentStatus  @default(PENDING)\n  paidAt            DateTime?\n  refundedAt        DateTime?\n  metadata          Json?\n  createdAt         DateTime       @default(now())\n  updatedAt         DateTime       @updatedAt\n\n  order             Order          @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  store             Store          @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([status])\n  @@index([gateway])\n  @@map(\"payments\")\n}\n\n// ─── Subscription ────────────────────────────────────────────────────────────\n\nmodel Subscription {\n  id                  String             @id @default(uuid())\n  userId              String             @unique\n  plan                PlanType           @default(STARTER)\n  status              SubscriptionStatus @default(ACTIVE)\n  currentPeriodStart  DateTime\n  currentPeriodEnd    DateTime\n  cancelAtPeriodEnd   Boolean            @default(false)\n  stripeSubId         String?\n  paystackSubCode     String?\n  price               Float\n  currency            String             @default(\"USD\")\n  createdAt           DateTime           @default(now())\n  updatedAt           DateTime           @updatedAt\n\n  user                User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([status])\n  @@map(\"subscriptions\")\n}\n\n// ─── Analytics ───────────────────────────────────────────────────────────────\n\nmodel Analytics {\n  id            String   @id @default(uuid())\n  storeId       String\n  date          DateTime @db.Date\n  views         Int      @default(0)\n  visitors      Int      @default(0)\n  orders        Int      @default(0)\n  revenue       Float    @default(0)\n  conversions   Float    @default(0)\n  avgOrderValue Float    @default(0)\n  newCustomers  Int      @default(0)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  store         Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@unique([storeId, date])\n  @@index([storeId])\n  @@map(\"analytics\")\n}\n\n// ─── Shipping Zone ───────────────────────────────────────────────────────────\n\n\n// ─── Support Ticket ──────────────────────────────────────────────────────────\n\nmodel SupportTicket {\n  id          String        @id @default(uuid())\n  userId      String\n  subject     String\n  message     String\n  status      SupportStatus @default(OPEN)\n  priority    Priority      @default(MEDIUM)\n  adminReply  String?\n  resolvedAt  DateTime?\n  createdAt   DateTime      @default(now())\n  updatedAt   DateTime      @updatedAt\n\n  user        User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  replies     TicketReply[]\n\n  @@index([userId])\n  @@index([status])\n  @@map(\"support_tickets\")\n}\n\nmodel TicketReply {\n  id        String        @id @default(uuid())\n  ticketId  String\n  senderId  String\n  isAdmin   Boolean       @default(false)\n  message   String\n  createdAt DateTime      @default(now())\n\n  ticket    SupportTicket @relation(fields: [ticketId], references: [id], onDelete: Cascade)\n\n  @@index([ticketId])\n  @@map(\"ticket_replies\")\n}\n\n// ─── Platform Settings ───────────────────────────────────────────────────────\n\nmodel PlatformSettings {\n  id                  String   @id @default(\"singleton\")\n  platformFeePercent  Float    @default(10)\n  starterPrice        Float    @default(9)\n  proPrice            Float    @default(29)\n  advancedPrice       Float    @default(79)\n  maintenanceMode     Boolean  @default(false)\n  allowRegistration   Boolean  @default(true)\n  maxStoresPerOwner   Json     @default(\"{\\\"STARTER\\\":1,\\\"PRO\\\":3,\\\"ADVANCED\\\":999}\")\n  maxProductsPerStore Json     @default(\"{\\\"STARTER\\\":50,\\\"PRO\\\":500,\\\"ADVANCED\\\":999999}\")\n  smtpConfig          Json?\n  updatedAt           DateTime @updatedAt\n\n  @@map(\"platform_settings\")\n}\n\n// ─── Notification ────────────────────────────────────────────────────────────\n\nmodel Notification {\n  id        String   @id @default(uuid())\n  userId    String\n  title     String\n  message   String\n  type      String   @default(\"info\")\n  read      Boolean  @default(false)\n  link      String?\n  createdAt DateTime @default(now())\n\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([read])\n  @@map(\"notifications\")\n}\n\n// ─── Audit Log ───────────────────────────────────────────────────────────────\n\nmodel AuditLog {\n  id          String   @id @default(uuid())\n  userId      String?\n  action      String\n  entity      String\n  entityId    String?\n  oldValues   Json?\n  newValues   Json?\n  ipAddress   String?\n  userAgent   String?\n  level       LogLevel @default(INFO)\n  createdAt   DateTime @default(now())\n\n  user        User?    @relation(fields: [userId], references: [id])\n\n  @@index([userId])\n  @@index([entity])\n  @@index([createdAt])\n  @@map(\"audit_logs\")\n}\n\n// ─── Error Log ───────────────────────────────────────────────────────────────\n\nmodel ErrorLog {\n  id          String   @id @default(uuid())\n  message     String\n  stack       String?\n  path        String?\n  method      String?\n  statusCode  Int?\n  userId      String?\n  ipAddress   String?\n  resolved    Boolean  @default(false)\n  createdAt   DateTime @default(now())\n\n  @@index([resolved])\n  @@index([createdAt])\n  @@map(\"error_logs\")\n}\n\n// ─── Coupon ──────────────────────────────────────────────────────────────────\n\nmodel Coupon {\n  id            String    @id @default(uuid())\n  storeId       String\n  code          String\n  type          String    // PERCENTAGE | FIXED\n  value         Float\n  minOrderValue Float     @default(0)\n  maxUses       Int?\n  usedCount     Int       @default(0)\n  isActive      Boolean   @default(true)\n  expiresAt     DateTime?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  store         Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@unique([storeId, code])\n  @@index([storeId])\n  @@map(\"coupons\")\n}\n\n// ─── Shipping Zone ───────────────────────────────────────────────────────────\n\nmodel ShippingZone {\n  id            String   @id @default(uuid())\n  storeId       String\n  name          String\n  countries     String[]\n  shippingRate  Float    @default(0)\n  freeThreshold Float?\n  estimatedDays String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  store         Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@map(\"shipping_zones\")\n}\n\n// ─── Review ──────────────────────────────────────────────────────────────────\n\nmodel Review {\n  id         String   @id @default(uuid())\n  storeId    String\n  productId  String\n  name       String\n  email      String\n  rating     Int      // 1-5\n  title      String?\n  body       String\n  photos     String[] // array of image URLs\n  approved   Boolean  @default(false)\n  featured   Boolean  @default(false)\n  helpful    Int      @default(0)\n  verified   Boolean  @default(false)\n  orderId    String?  // set if from verified purchase\n  replyBody  String?  // store owner reply\n  repliedAt  DateTime?\n  source     String?  // \"email\" | \"in-app\" | \"import\"\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  store   Store   @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@index([productId])\n  @@index([storeId])\n  @@map(\"reviews\")\n}\n\n// ─── Abandoned Cart ───────────────────────────────────────────────────────────\n\nmodel AbandonedCart {\n  id            String   @id @default(uuid())\n  storeId       String\n  email         String\n  name          String?\n  items         Json     // CartItem[]\n  total         Float\n  currency      String   @default(\"USD\")\n  token         String   @unique @default(uuid())  // recovery link token\n  recovered     Boolean  @default(false)\n  emailSent     Boolean  @default(false)\n  emailSentAt   DateTime?\n  recoveredAt   DateTime?\n  reminderCount Int      @default(0)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  store         Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([email])\n  @@index([token])\n  @@index([recovered, emailSent])\n  @@map(\"abandoned_carts\")\n}\n\n// ─── Supplier ─────────────────────────────────────────────────────────────────\n\nmodel Supplier {\n  id           String       @id @default(uuid())\n  storeId      String\n  name         String\n  type         SupplierType @default(MANUAL)\n  websiteUrl   String?\n  apiKey       String?\n  apiSecret    String?\n  contactEmail String?\n  contactName  String?\n  notes        String?\n  isActive     Boolean      @default(true)\n  autoFulfill  Boolean      @default(false)  // auto-forward orders when PROCESSING\n  fulfillEmail String?                        // email to send order details to\n  webhookUrl   String?                        // POST order JSON here on new order\n  createdAt    DateTime     @default(now())\n  updatedAt    DateTime     @updatedAt\n\n  store            Store             @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  products         SupplierProduct[]\n  fulfillmentOrders FulfillmentOrder[]\n\n  @@index([storeId])\n  @@map(\"suppliers\")\n}\n\nmodel SupplierProduct {\n  id              String   @id @default(uuid())\n  supplierId      String\n  productId       String\n  supplierSku     String?             // SKU in supplier's system\n  supplierUrl     String?             // original product URL (e.g. AliExpress)\n  supplierPrice   Float?              // cost from supplier (in supplier's currency)\n  supplierCurrency String  @default(\"USD\")\n  processingDays  Int?                // how many days to process\n  shippingDays    Int?                // estimated shipping\n  lastSynced      DateTime?\n  stockStatus     String?             // \"IN_STOCK\" | \"LOW_STOCK\" | \"OUT_OF_STOCK\"\n  priority        Int      @default(1)  // 1 = primary, higher = fallback\n  isActive        Boolean  @default(true)\n  notes           String?             // internal notes\n  createdAt       DateTime @default(now())\n\n  supplier  Supplier @relation(fields: [supplierId], references: [id], onDelete: Cascade)\n  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@unique([supplierId, productId])\n  @@index([productId])\n  @@map(\"supplier_products\")\n}\n\nmodel FulfillmentOrder {\n  id          String            @id @default(uuid())\n  orderId     String\n  supplierId  String\n  storeId     String\n  status      FulfillmentStatus @default(PENDING)\n  sentAt      DateTime?\n  confirmedAt DateTime?\n  notes       String?\n  supplierRef String?           // reference/tracking from supplier\n  method      String?           // \"EMAIL\" | \"WEBHOOK\" | \"MANUAL\"\n  payload     Json?             // what was sent to supplier\n  createdAt   DateTime          @default(now())\n  updatedAt   DateTime          @updatedAt\n\n  supplier Supplier @relation(fields: [supplierId], references: [id])\n  store    Store    @relation(fields: [storeId],    references: [id], onDelete: Cascade)\n\n  @@index([orderId])\n  @@index([supplierId])\n  @@index([storeId])\n  @@map(\"fulfillment_orders\")\n}\n\n\nenum SupplierType {\n  MANUAL\n  ALIEXPRESS\n  CSV\n  WEBHOOK\n}\n\nenum FulfillmentStatus {\n  PENDING\n  SENT\n  CONFIRMED\n  SHIPPED\n  FAILED\n}\n\n\n// ─── Discount Engine ─────────────────────────────────────────────────────────\n\nmodel Discount {\n  id          String       @id @default(uuid())\n  storeId     String\n  name        String\n  description String?\n  type        DiscountType\n  status      DiscountStatus @default(ACTIVE)\n  priority    Int          @default(0)   // higher = applied first\n  stackable   Boolean      @default(false)\n\n  // Trigger conditions\n  minOrderValue    Float?\n  minQuantity      Int?\n  customerTag      String?  // e.g. \"VIP\", \"wholesale\"\n  productIds       String[] // empty = all products\n  collectionIds    String[]\n  firstOrderOnly   Boolean  @default(false)\n\n  // Value / Action\n  valueType   DiscountValueType\n  value       Float             // %, fixed $, or new price\n  maxDiscount Float?            // cap on percentage discounts\n  freeShipping Boolean          @default(false)\n\n  // BOGO fields\n  bogoRequiredQty  Int?         // buy X\n  bogoGetQty       Int?         // get Y\n  bogoPctOff       Float?       // discount on the free item (100 = fully free)\n\n  // Tiered pricing (JSON array of {qty, pct})\n  tiers       Json?            // [{minQty:2,discount:10},{minQty:5,discount:20}]\n\n  // Flash sale\n  flashSaleEndsAt DateTime?\n  flashSaleStartsAt DateTime?\n\n  // Usage limits\n  maxUses       Int?\n  maxUsesPerCustomer Int?\n  usedCount     Int       @default(0)\n\n  // Validity\n  startsAt   DateTime?\n  expiresAt  DateTime?\n  isAutomatic Boolean   @default(false) // no code needed\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  store  Store            @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  usages DiscountUsage[]\n\n  @@index([storeId])\n  @@map(\"discounts\")\n}\n\nmodel DiscountUsage {\n  id          String   @id @default(uuid())\n  discountId  String\n  orderId     String\n  customerId  String?\n  amountSaved Float\n  appliedAt   DateTime @default(now())\n\n  discount Discount @relation(fields: [discountId], references: [id], onDelete: Cascade)\n\n  @@index([discountId])\n  @@index([orderId])\n  @@map(\"discount_usages\")\n}\n\nenum DiscountType {\n  AUTOMATIC     // applies automatically at checkout\n  BOGO          // buy X get Y\n  TIERED        // volume tiers\n  FLASH_SALE    // time-limited\n  PERCENTAGE    // classic % off\n  FIXED         // fixed $ off\n  FREE_SHIPPING // free shipping\n  BUNDLE        // spend X get Y\n}\n\nenum DiscountStatus {\n  ACTIVE\n  PAUSED\n  EXPIRED\n  SCHEDULED\n}\n\nenum DiscountValueType {\n  PERCENTAGE\n  FIXED_AMOUNT\n  NEW_PRICE\n  FREE\n}\n\n// ─── Referral & Affiliate System ─────────────────────────────────────────────\n\nmodel Affiliate {\n  id          String          @id @default(uuid())\n  storeId     String\n  name        String\n  email       String\n  code        String          // unique referral code\n  status      AffiliateStatus @default(PENDING)\n  commissionPct Float         @default(10)  // % of order value\n  commissionFlat Float?       // flat $ per sale (override)\n  payoutMethod  String?       // \"paypal\" | \"bank\" | \"store_credit\"\n  payoutDetails Json?         // encrypted payout info\n  totalEarned   Float         @default(0)\n  totalPaid     Float         @default(0)\n  totalClicks   Int           @default(0)\n  totalOrders   Int           @default(0)\n  notes         String?\n  createdAt   DateTime        @default(now())\n  updatedAt   DateTime        @updatedAt\n\n  store     Store             @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  referrals ReferralConversion[]\n  payouts   AffiliatePayout[]\n\n  @@unique([storeId, code])\n  @@index([storeId])\n  @@map(\"affiliates\")\n}\n\nmodel ReferralConversion {\n  id          String   @id @default(uuid())\n  affiliateId String\n  orderId     String\n  storeId     String\n  orderValue  Float\n  commission  Float\n  status      String   @default(\"PENDING\")  // PENDING | APPROVED | PAID | REJECTED\n  createdAt   DateTime @default(now())\n\n  affiliate Affiliate @relation(fields: [affiliateId], references: [id], onDelete: Cascade)\n\n  @@index([affiliateId])\n  @@index([orderId])\n  @@map(\"referral_conversions\")\n}\n\nmodel AffiliatePayout {\n  id          String   @id @default(uuid())\n  affiliateId String\n  storeId     String\n  amount      Float\n  method      String\n  status      String   @default(\"PENDING\")  // PENDING | SENT | FAILED\n  reference   String?\n  note        String?\n  createdAt   DateTime @default(now())\n\n  affiliate Affiliate @relation(fields: [affiliateId], references: [id], onDelete: Cascade)\n\n  @@index([affiliateId])\n  @@map(\"affiliate_payouts\")\n}\n\n// Affiliate click tracking\nmodel ReferralClick {\n  id          String   @id @default(uuid())\n  affiliateId String\n  storeId     String\n  ip          String?\n  userAgent   String?\n  page        String?\n  converted   Boolean  @default(false)\n  createdAt   DateTime @default(now())\n\n  @@index([affiliateId])\n  @@map(\"referral_clicks\")\n}\n\nenum AffiliateStatus {\n  PENDING\n  ACTIVE\n  PAUSED\n  SUSPENDED\n}\n\n// ─── Web Push Subscriptions ──────────────────────────────────────────────────\n\nmodel PushSubscription {\n  id       String   @id @default(uuid())\n  userId   String\n  endpoint String   @unique\n  p256dh   String   // public key\n  auth     String   // auth secret\n  deviceName String?  // e.g. \"Chrome on iPhone\"\n  isActive Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"push_subscriptions\")\n}\n\n// ─── Refund & Dispute ────────────────────────────────────────────────────────\n\nenum RefundStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  PROCESSED\n}\n\nenum RefundReason {\n  DAMAGED\n  NOT_RECEIVED\n  WRONG_ITEM\n  NOT_AS_DESCRIBED\n  CHANGED_MIND\n  OTHER\n}\n\nmodel Refund {\n  id          String       @id @default(uuid())\n  orderId     String\n  storeId     String\n  amount      Float\n  reason      RefundReason\n  description String?\n  status      RefundStatus @default(PENDING)\n  gatewayRef  String?      // gateway refund ID\n  processedAt DateTime?\n  adminNote   String?\n  photos      String[]     @default([])\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  order       Order        @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  store       Store        @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([orderId])\n  @@index([storeId])\n  @@map(\"refunds\")\n}\n\n// ─── Customer Accounts ───────────────────────────────────────────────────────\n\nmodel CustomerAccount {\n  id            String    @id @default(uuid())\n  storeId       String\n  email         String\n  name          String\n  phone         String?\n  passwordHash  String\n  emailVerified Boolean   @default(false)\n  verifyToken   String?\n  resetToken    String?\n  resetExpiry   DateTime?\n  refreshToken  String?\n  defaultAddress Json?\n  savedAddresses Json[]   @default([])\n  wishlist       String[] @default([]) // productIds\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  @@unique([storeId, email])\n  @@index([storeId])\n  @@map(\"customer_accounts\")\n}\n\n// ─── Wishlist ────────────────────────────────────────────────────────────────\n\nmodel Wishlist {\n  id         String   @id @default(uuid())\n  storeId    String\n  email      String\n  productId  String\n  createdAt  DateTime @default(now())\n\n  @@unique([storeId, email, productId])\n  @@index([storeId, email])\n  @@map(\"wishlists\")\n}\n\n// ─── Gift Card ───────────────────────────────────────────────────────────────\n\nmodel GiftCard {\n  id          String    @id @default(uuid())\n  storeId     String\n  code        String    @unique\n  balance     Float\n  initialAmount Float\n  currency    String    @default(\"USD\")\n  isActive    Boolean   @default(true)\n  purchasedBy String?   // email\n  assignedTo  String?   // email\n  expiresAt   DateTime?\n  note        String?\n  redeemedAmount Float  @default(0)\n  usages      GiftCardUsage[]\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  store       Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([code])\n  @@map(\"gift_cards\")\n}\n\nmodel GiftCardUsage {\n  id         String   @id @default(uuid())\n  giftCardId String\n  orderId    String\n  amount     Float\n  createdAt  DateTime @default(now())\n\n  giftCard   GiftCard @relation(fields: [giftCardId], references: [id], onDelete: Cascade)\n\n  @@index([giftCardId])\n  @@map(\"gift_card_usages\")\n}\n\n// ─── Funnel Analytics ────────────────────────────────────────────────────────\n\nmodel FunnelEvent {\n  id        String   @id @default(uuid())\n  storeId   String\n  sessionId String\n  event     String   // \"view\" | \"add_to_cart\" | \"checkout_start\" | \"purchase\"\n  productId String?\n  orderId   String?\n  value     Float?\n  meta      Json?\n  ip        String?\n  userAgent String?\n  createdAt DateTime @default(now())\n\n  @@index([storeId])\n  @@index([sessionId])\n  @@index([event])\n  @@index([createdAt])\n  @@map(\"funnel_events\")\n}\n\n// ─── UTM / Traffic Source ────────────────────────────────────────────────────\n\nmodel UtmSession {\n  id         String   @id @default(uuid())\n  storeId    String\n  sessionId  String\n  source     String?\n  medium     String?\n  campaign   String?\n  term       String?\n  content    String?\n  landingPage String?\n  referrer   String?\n  converted  Boolean  @default(false)\n  orderId    String?\n  orderValue Float?\n  createdAt  DateTime @default(now())\n\n  @@unique([storeId, sessionId])\n  @@index([storeId])\n  @@index([source])\n  @@map(\"utm_sessions\")\n}\n\n// ─── API Keys (store owner) ─────────────────────────────────────────────────\n\nmodel ApiKey {\n  id          String    @id @default(uuid())\n  storeId     String\n  name        String\n  keyHash     String    @unique  // SHA-256 of actual key\n  keyPrefix   String             // first 8 chars for display\n  permissions String[]  @default([]) // [\"orders:read\",\"products:write\",...]\n  isActive    Boolean   @default(true)\n  lastUsedAt  DateTime?\n  expiresAt   DateTime?\n  createdAt   DateTime  @default(now())\n\n  store       Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([keyHash])\n  @@map(\"api_keys\")\n}\n\n// ─── Store Backup ────────────────────────────────────────────────────────────\n\nmodel StoreBackup {\n  id        String   @id @default(uuid())\n  storeId   String\n  fileName  String\n  fileUrl   String\n  fileSize  Int?     // bytes\n  status    String   @default(\"PENDING\") // PENDING | READY | FAILED\n  createdAt DateTime @default(now())\n\n  store     Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@map(\"store_backups\")\n}\n\n// ─── Outgoing Webhooks (store owner) ────────────────────────────────────────\n\nmodel StoreWebhook {\n  id        String   @id @default(uuid())\n  storeId   String\n  url       String\n  events    String[] // [\"order.created\",\"order.paid\",\"product.updated\",...]\n  secret    String\n  isActive  Boolean  @default(true)\n  lastFiredAt DateTime?\n  failCount  Int     @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  store      Store            @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  deliveries WebhookDelivery[]\n\n  @@index([storeId])\n  @@map(\"store_webhooks\")\n}\n\nmodel WebhookDelivery {\n  id         String   @id @default(uuid())\n  webhookId  String\n  event      String\n  payload    Json\n  statusCode Int?\n  response   String?\n  success    Boolean  @default(false)\n  createdAt  DateTime @default(now())\n\n  webhook StoreWebhook @relation(fields: [webhookId], references: [id], onDelete: Cascade)\n\n  @@index([webhookId])\n  @@map(\"webhook_deliveries\")\n}\n\n// ─── Flash Sale ──────────────────────────────────────────────────────────────\n\nmodel FlashSale {\n  id          String   @id @default(uuid())\n  storeId     String\n  name        String\n  discountPct Float\n  productIds  String[]\n  startsAt    DateTime\n  endsAt      DateTime\n  isActive    Boolean  @default(true)\n  bannerText  String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  store       Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@map(\"flash_sales\")\n}\n\n// ─── Return / RMA ────────────────────────────────────────────────────────────\n\nenum ReturnStatus {\n  REQUESTED\n  APPROVED\n  REJECTED\n  RECEIVED\n  REFUNDED\n}\n\nmodel ReturnRequest {\n  id          String       @id @default(uuid())\n  orderId     String\n  storeId     String\n  customerEmail String\n  reason      String\n  description String?\n  photos      String[]     @default([])\n  status      ReturnStatus @default(REQUESTED)\n  trackingNumber String?\n  adminNote   String?\n  resolvedAt  DateTime?\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  order       Order        @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  store       Store        @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([orderId])\n  @@index([storeId])\n  @@map(\"return_requests\")\n}\n\n// ─── Subscription Products ───────────────────────────────────────────────────\n\nmodel ProductSubscription {\n  id            String   @id @default(uuid())\n  storeId       String\n  productId     String\n  customerEmail String\n  interval      String   // \"weekly\" | \"monthly\" | \"quarterly\"\n  intervalCount Int      @default(1)\n  price         Float\n  currency      String   @default(\"USD\")\n  discount      Float    @default(0) // % off for subscribing\n  status        String   @default(\"ACTIVE\") // ACTIVE | PAUSED | CANCELLED\n  nextBillingAt DateTime\n  stripeSubId   String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  @@index([storeId])\n  @@index([customerEmail])\n  @@map(\"product_subscriptions\")\n}\n\n// ─── Cohort Analytics ────────────────────────────────────────────────────────\n\nmodel CohortData {\n  id        String   @id @default(uuid())\n  storeId   String\n  cohortMonth String  // \"2025-01\"\n  totalCustomers Int @default(0)\n  day30Return    Int @default(0)\n  day60Return    Int @default(0)\n  day90Return    Int @default(0)\n  calculatedAt   DateTime @default(now())\n\n  @@unique([storeId, cohortMonth])\n  @@index([storeId])\n  @@map(\"cohort_data\")\n}\n\n// ─── KAI Chat History ─────────────────────────────────────────────────────────\n\nmodel KaiConversation {\n  id        String       @id @default(uuid())\n  userId    String\n  title     String       @default(\"New Chat\")\n  createdAt DateTime     @default(now())\n  updatedAt DateTime     @updatedAt\n  messages  KaiMessage[]\n\n  user      User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"kai_conversations\")\n}\n\nmodel KaiMessage {\n  id             String          @id @default(uuid())\n  conversationId String\n  role           String          // \"user\" | \"assistant\"\n  content        String          @db.Text\n  action         String?\n  createdAt      DateTime        @default(now())\n\n  conversation   KaiConversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n\n  @@index([conversationId])\n  @@map(\"kai_messages\")\n}\n\n\nmodel StoreIntegration {\n  id           String    @id @default(cuid())\n  storeId      String\n  store        Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  provider     String\n  email        String?\n  password     String?\n  accessToken  String?   @db.Text\n  refreshToken String?\n  expiresAt    DateTime?\n  isActive     Boolean   @default(true)\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  @@unique([storeId, provider], name: \"storeId_provider\")\n  @@index([storeId])\n}\n\nmodel WaitlistEntry {\n  id           String   @id @default(cuid())\n  name         String\n  email        String   @unique\n  whatsapp     String?\n  spotNumber   Int      @unique\n  referralCode String   @unique\n  referredBy   String?\n  source       String?\n  ipHash       String?\n  confirmed    Boolean  @default(false)\n  createdAt    DateTime @default(now())\n\n  @@index([email])\n  @@index([referralCode])\n  @@index([spotNumber])\n}\n\nmodel Bundle {\n  id              String   @id @default(uuid())\n  storeId         String\n  store           Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  name            String\n  productIds      String[]\n  discountPercent Float    @default(10)\n  bundlePrice     Float?\n  originalPrice   Float?\n  active          Boolean  @default(true)\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n}\n\nmodel GroupBuy {\n  id              String        @id @default(uuid())\n  storeId         String\n  store           Store         @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  productId       String\n  product         Product       @relation(fields: [productId], references: [id])\n  title           String\n  description     String?\n  groupPrice      Float\n  originalPrice   Float\n  minMembers      Int\n  endsAt          DateTime\n  active          Boolean       @default(true)\n  members         GroupBuyMember[]\n  createdAt       DateTime      @default(now())\n}\n\nmodel GroupBuyMember {\n  id          String   @id @default(uuid())\n  groupBuyId  String\n  groupBuy    GroupBuy @relation(fields: [groupBuyId], references: [id], onDelete: Cascade)\n  name        String\n  email       String\n  paid        Boolean  @default(false)\n  createdAt   DateTime @default(now())\n}\n\nmodel Milestone {\n  id        String   @id @default(uuid())\n  storeId   String\n  store     Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  type      String\n  title     String\n  message   String\n  cta       Json?\n  seen      Boolean  @default(false)\n  createdAt DateTime @default(now())\n}\n\nmodel ContactMessage {\n  id        String   @id @default(uuid())\n  name      String\n  email     String\n  subject   String   @default(\"general\")\n  message   String\n  status    String   @default(\"new\")\n  createdAt DateTime @default(now())\n}\n\nmodel Referral {\n  id          String   @id @default(uuid())\n  userId      String   @unique\n  user        User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  code        String   @unique\n  clicks      Int      @default(0)\n  signups     Int      @default(0)\n  conversions Int      @default(0)\n  earned      Float    @default(0)\n  pending     Float    @default(0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\n\n\n\n\n\n\n\n\n\n\nmodel RefreshToken {\n  id          String    @id @default(uuid())\n  userId      String\n  user        User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  token       String    @unique\n  expiresAt   DateTime\n  revokedAt   DateTime?\n  ipAddress   String?\n  userAgent   String?\n  createdAt   DateTime  @default(now())\n  @@index([userId])\n  @@map(\"refresh_tokens\")\n}\n\nmodel KaiMemory {\n  id        String   @id @default(uuid())\n  userId    String\n  storeId   String?\n  key       String\n  value     String\n  ttl       DateTime?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  @@unique([userId, key])\n  @@map(\"kai_memories\")\n}\n\nmodel KaiGoal {\n  id          String   @id @default(uuid())\n  userId      String\n  storeId     String\n  title       String\n  description String?\n  target      Float?\n  current     Float    @default(0)\n  unit        String   @default(\"NGN\")\n  deadline    DateTime?\n  achieved    Boolean  @default(false)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  @@map(\"kai_goals\")\n}\n\nmodel KaiMarketCache {\n  id          String   @id @default(uuid())\n  key         String   @unique\n  data        Json\n  expiresAt   DateTime\n  createdAt   DateTime @default(now())\n  @@map(\"kai_market_cache\")\n}\n\nmodel KaiPulseAlert {\n  id        String   @id @default(uuid())\n  storeId   String\n  userId    String\n  type      String\n  title     String\n  message   String\n  data      Json?\n  read      Boolean  @default(false)\n  priority  String   @default(\"normal\")\n  createdAt DateTime @default(now())\n  @@index([storeId])\n  @@index([userId])\n  @@map(\"kai_pulse_alerts\")\n}\n\nmodel KaiMorningBrief {\n  id        String   @id @default(uuid())\n  userId    String\n  storeId   String\n  content   String\n  date      DateTime @default(now())\n  delivered Boolean  @default(false)\n  @@map(\"kai_morning_briefs\")\n}\n\nmodel KaiBrandVoice {\n  id         String   @id @default(uuid())\n  storeId    String   @unique\n  tone       String   @default(\"friendly\")\n  style      String   @default(\"conversational\")\n  keywords   String[] @default([])\n  avoidWords String[] @default([])\n  examples   String[] @default([])\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n  @@map(\"kai_brand_voices\")\n}\n\nmodel KaiSkill {\n  id          String   @id @default(uuid())\n  userId      String\n  name        String\n  description String?\n  prompt      String\n  useCount    Int      @default(0)\n  active      Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  @@index([userId])\n  @@map(\"kai_skills\")\n}\n\nmodel LoyaltyAccount {\n  id           String   @id @default(uuid())\n  storeId      String\n  customerId   String\n  points       Int      @default(0)\n  totalEarned  Int      @default(0)\n  totalSpent   Int      @default(0)\n  tier         String   @default(\"bronze\")\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n  @@unique([storeId, customerId])\n  @@map(\"loyalty_accounts\")\n}\n\nmodel ReviewRequest {\n  id         String   @id @default(uuid())\n  orderId    String   @unique\n  storeId    String\n  customerId String?\n  email      String\n  sentAt     DateTime?\n  responded  Boolean  @default(false)\n  createdAt  DateTime @default(now())\n  @@map(\"review_requests\")\n}\n","backend/tsconfig.json":"{\n  \"compilerOptions\": {\n    \"target\": \"ES2020\",\n    \"module\": \"commonjs\",\n    \"lib\": [\n      \"ES2020\"\n    ],\n    \"outDir\": \"./dist\",\n    \"rootDir\": \"./src\",\n    \"strict\": false,\n    \"esModuleInterop\": true,\n    \"skipLibCheck\": true,\n    \"forceConsistentCasingInFileNames\": true,\n    \"resolveJsonModule\": true,\n    \"declaration\": true,\n    \"declarationMap\": true,\n    \"sourceMap\": true,\n    \"experimentalDecorators\": true,\n    \"emitDecoratorMetadata\": true,\n    \"paths\": {\n      \"@/*\": [\n        \"./src/*\"\n      ]\n    },\n    \"baseUrl\": \".\",\n    \"noImplicitAny\": false\n  },\n  \"include\": [\n    \"src/**/*\",\n    \"prisma/seed.ts\"\n  ],\n  \"exclude\": [\n    \"node_modules\",\n    \"dist\",\n    \"prisma\",\n    \"src/utils/app.additions.ts\"\n  ]\n}","backend/package.json":"{\n  \"name\": \"dropos-backend\",\n  \"version\": \"1.0.0\",\n  \"description\": \"DropOS SaaS Dropshipping Platform \\u2014 Backend API\",\n  \"main\": \"dist/server.js\",\n  \"scripts\": {\n    \"dev\": \"ts-node-dev --respawn --transpile-only src/server.ts\",\n    \"build\": \"npx tsc --skipLibCheck\",\n    \"start\": \"node --max-old-space-size=400 dist/server.js\",\n    \"seed\": \"npx ts-node prisma/seed.ts\",\n    \"generate\": \"npx prisma generate\",\n    \"migrate\": \"npx prisma migrate dev\",\n    \"studio\": \"npx prisma studio\"\n  },\n  \"dependencies\": {\n    \"@prisma/client\": \"^5.7.0\",\n    \"@types/node\": \"^20.10.0\",\n    \"axios\": \"^1.6.2\",\n    \"bcryptjs\": \"^2.4.3\",\n    \"cloudinary\": \"^2.0.0\",\n    \"compression\": \"^1.7.4\",\n    \"cookie-parser\": \"^1.4.6\",\n    \"cors\": \"^2.8.5\",\n    \"dotenv\": \"^16.3.1\",\n    \"express\": \"^4.18.2\",\n    \"express-async-errors\": \"^3.1.1\",\n    \"express-rate-limit\": \"^7.1.5\",\n    \"express-validator\": \"^7.0.1\",\n    \"helmet\": \"^7.1.0\",\n    \"jsonwebtoken\": \"^9.0.2\",\n    \"morgan\": \"^1.10.0\",\n    \"multer\": \"^1.4.5-lts.1\",\n    \"node-fetch\": \"^2.7.0\",\n    \"nodemailer\": \"^6.9.7\",\n    \"prisma\": \"^5.7.0\",\n    \"qrcode\": \"^1.5.3\",\n    \"resend\": \"^6.10.0\",\n    \"speakeasy\": \"^2.0.0\",\n    \"stripe\": \"^14.9.0\",\n    \"ts-node\": \"^10.9.1\",\n    \"twilio\": \"^4.19.0\",\n    \"typescript\": \"^5.3.2\",\n    \"uuid\": \"^9.0.1\",\n    \"web-push\": \"^3.6.7\",\n    \"winston\": \"^3.11.0\",\n    \"zod\": \"^3.22.4\"\n  },\n  \"devDependencies\": {\n    \"@types/bcryptjs\": \"^2.4.6\",\n    \"@types/compression\": \"^1.7.5\",\n    \"@types/cookie-parser\": \"^1.4.6\",\n    \"@types/cors\": \"^2.8.17\",\n    \"@types/express\": \"^4.17.21\",\n    \"@types/jsonwebtoken\": \"^9.0.5\",\n    \"@types/morgan\": \"^1.9.9\",\n    \"@types/multer\": \"^1.4.11\",\n    \"@types/node-fetch\": \"^2.6.11\",\n    \"@types/nodemailer\": \"^6.4.14\",\n    \"@types/qrcode\": \"^1.5.5\",\n    \"@types/speakeasy\": \"^2.0.8\",\n    \"@types/twilio\": \"^3.19.3\",\n    \"@types/uuid\": \"^9.0.7\",\n    \"@types/web-push\": \"^3.6.3\",\n    \"ts-node-dev\": \"^2.0.0\"\n  }\n}","backend/src/services/kai.pulse.service.ts":"// ============================================================\n// KAI — Pulse Service\n// Path: backend/src/services/kai.pulse.service.ts\n// Runs 24/7 in background, surfaces insights before owner asks\n// ============================================================\nimport { PrismaClient } from \"@prisma/client\";\nimport { getStoreContext } from \"./kai.service\";\n\nconst prisma = new PrismaClient();\n\n// ── Create a pulse alert ──────────────────────────────────────\nasync function createAlert(\n  storeId: string,\n  type: string,\n  title: string,\n  message: string,\n  severity: \"info\" | \"warning\" | \"critical\" | \"opportunity\",\n  suggestedPrompt?: string,\n  data?: any\n): Promise<void> {\n  // Don't duplicate alerts of same type within 6 hours\n  const recent = await prisma.kaiPulseAlert.findFirst({\n    where: {\n      storeId, type,\n      createdAt: { gte: new Date(Date.now() - 6 * 60 * 60 * 1000) },\n    },\n  });\n  if (recent) return;\n\n  await prisma.kaiPulseAlert.create({\n    data: {\n      storeId, type, title, message, severity,\n      actionable: !!suggestedPrompt,\n      suggestedPrompt,\n      data,\n    },\n  });\n}\n\n// ── Analyze a single store ────────────────────────────────────\nexport async function analyzeStore(storeId: string): Promise<void> {\n  try {\n    const ctx = await getStoreContext(storeId);\n\n    // 1. Unfulfilled orders > 48 hours\n    if (ctx.pendingOrders > 0) {\n      const oldOrders = await prisma.order.findMany({\n        where: {\n          storeId,\n          status: { in: [\"PENDING\", \"PROCESSING\"] },\n          createdAt: { lte: new Date(Date.now() - 48 * 60 * 60 * 1000) },\n        },\n        take: 5,\n      });\n      if (oldOrders.length > 0) {\n        await createAlert(storeId,\n          \"unfulfilled_orders\",\n          `${oldOrders.length} orders waiting over 48 hours`,\n          `You have ${oldOrders.length} orders that haven't been shipped in over 2 days. Customers are waiting. Let me help you fulfill them now.`,\n          \"warning\",\n          `Help me fulfill my ${oldOrders.length} overdue orders`,\n          { count: oldOrders.length }\n        );\n      }\n    }\n\n    // 2. Conversion rate drop\n    const last7Days = await prisma.order.count({\n      where: {\n        storeId,\n        createdAt: { gte: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000) },\n        status: { in: [\"COMPLETED\", \"SHIPPED\", \"DELIVERED\"] },\n      },\n    });\n    const prev7Days = await prisma.order.count({\n      where: {\n        storeId,\n        createdAt: {\n          gte: new Date(Date.now() - 14 * 24 * 60 * 60 * 1000),\n          lte: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000),\n        },\n        status: { in: [\"COMPLETED\", \"SHIPPED\", \"DELIVERED\"] },\n      },\n    });\n    if (prev7Days > 0 && last7Days < prev7Days * 0.6) {\n      const drop = Math.round((1 - last7Days / prev7Days) * 100);\n      await createAlert(storeId,\n        \"conversion_drop\",\n        `Sales dropped ${drop}% this week`,\n        `Your sales are down ${drop}% compared to last week. Something changed. Let me diagnose what's happening and suggest fixes.`,\n        \"critical\",\n        \"My sales dropped this week — diagnose what's wrong and help me fix it\",\n        { drop, last7Days, prev7Days }\n      );\n    }\n\n    // 3. Critical low stock\n    const criticalStock = await prisma.product.findMany({\n      where: { storeId, stockQuantity: { lte: 2, gt: 0 } },\n      select: { name: true, stockQuantity: true },\n      take: 5,\n    });\n    if (criticalStock.length > 0) {\n      await createAlert(storeId,\n        \"low_stock_critical\",\n        `${criticalStock.length} products almost out of stock`,\n        `${criticalStock.map(p => p.name).join(\", \")} — all have 2 or fewer units left. You'll miss sales if you don't reorder now.`,\n        \"warning\",\n        `Show me my critical low stock products and help me reorder`,\n        { products: criticalStock }\n      );\n    }\n\n    // 4. Revenue milestone approaching\n    const goals = await prisma.kaiGoal.findMany({\n      where: { storeId, status: \"active\" },\n    });\n    for (const goal of goals) {\n      const progress = (goal.currentValue / goal.targetValue) * 100;\n      if (progress >= 80 && progress < 100) {\n        const remaining = goal.targetValue - goal.currentValue;\n        await createAlert(storeId,\n          \"revenue_goal\",\n          `${Math.round(progress)}% toward your goal!`,\n          `You're ${Math.round(progress)}% toward \"${goal.title}\". Only ${goal.unit === \"NGN\" ? \"₦\" : \"\"}${remaining.toLocaleString()} ${goal.unit} left to reach it. Let's push!`,\n          \"opportunity\",\n          `I'm close to my goal — what should I do right now to hit it?`,\n          { goal: goal.title, progress, remaining }\n        );\n      }\n    }\n\n    // 5. Revenue opportunity - no sales today but it's afternoon\n    const hour = new Date().getHours();\n    if (hour >= 14 && ctx.revenueToday === 0 && ctx.totalProducts > 0) {\n      await createAlert(storeId,\n        \"pricing_opportunity\",\n        \"No sales yet today — let's change that\",\n        \"It's already afternoon and no orders today. A quick WhatsApp broadcast or flash sale could turn this around. Want me to set one up?\",\n        \"opportunity\",\n        \"Help me get a sale today — create a flash sale or WhatsApp broadcast\",\n        {}\n      );\n    }\n\n  } catch (err) {\n    console.error(`KAI Pulse analysis error for store ${storeId}:`, err);\n  }\n}\n\n// ── Analyze all stores (called by cron job) ───────────────────\nexport async function runPulseForAllStores(): Promise<void> {\n  const stores = await prisma.store.findMany({\n    where: { status: \"ACTIVE\" },\n    select: { id: true },\n  });\n\n  // Process in batches of 10 to avoid overload\n  const batchSize = 10;\n  for (let i = 0; i < stores.length; i += batchSize) {\n    const batch = stores.slice(i, i + batchSize);\n    await Promise.allSettled(batch.map(s => analyzeStore(s.id)));\n  }\n}\n\n// ── Get unread alerts for a store ────────────────────────────\nexport async function getUnreadAlerts(storeId: string) {\n  return prisma.kaiPulseAlert.findMany({\n    where: { storeId, read: false },\n    orderBy: [\n      { severity: \"desc\" },\n      { createdAt: \"desc\" },\n    ],\n    take: 10,\n  });\n}\n\n// ── Mark alert as read ────────────────────────────────────────\nexport async function markAlertRead(alertId: string): Promise<void> {\n  await prisma.kaiPulseAlert.update({\n    where: { id: alertId },\n    data: { read: true },\n  });\n}\n\n// ── Generate morning brief ────────────────────────────────────\nexport async function generateMorningBrief(storeId: string, apiKey: string): Promise<string> {\n  const today = new Date().toISOString().split(\"T\")[0];\n\n  // Check if already generated today\n  const existing = await prisma.kaiMorningBrief.findUnique({\n    where: { storeId_date: { storeId, date: today } },\n  });\n  if (existing) return existing.topOpportunity;\n\n  const ctx = await getStoreContext(storeId);\n  const midnight = new Date();\n  midnight.setHours(0, 0, 0, 0);\n\n  const overnightOrders = await prisma.order.count({\n    where: {\n      storeId,\n      createdAt: { gte: midnight },\n      status: { in: [\"COMPLETED\", \"SHIPPED\", \"DELIVERED\"] },\n    },\n  });\n\n  const overnightRevenue = await prisma.order.aggregate({\n    where: {\n      storeId,\n      createdAt: { gte: midnight },\n      status: { in: [\"COMPLETED\", \"SHIPPED\", \"DELIVERED\"] },\n    },\n    _sum: { total: true },\n  });\n\n  const revenueAmt = Number(overnightRevenue._sum.total || 0);\n  const sym = ctx.currency === \"NGN\" ? \"₦\" : ctx.currency === \"GBP\" ? \"£\" : \"$\";\n\n  // Generate opportunity using Claude\n  const response = await fetch(\"https://api.anthropic.com/v1/messages\", {\n    method: \"POST\",\n    headers: {\n      \"x-api-key\": apiKey,\n      \"anthropic-version\": \"2023-06-01\",\n      \"Content-Type\": \"application/json\",\n    },\n    body: JSON.stringify({\n      model: \"claude-haiku-4-5-20251001\",\n      max_tokens: 200,\n      messages: [{\n        role: \"user\",\n        content: `Store: ${ctx.storeName}, Country: ${ctx.country}\nOvernight: ${overnightOrders} orders, ${sym}${revenueAmt.toLocaleString()} revenue\nPending orders: ${ctx.pendingOrders}, Low stock: ${ctx.lowStockCount}\nProducts: ${ctx.totalProducts}\n\nWrite ONE sentence opportunity for today (no asterisks, no markdown, max 25 words). \nMake it specific and actionable for a Nigerian/African seller.`,\n      }],\n    }),\n  });\n\n  let opportunity = \"Focus on fulfilling pending orders and restocking low inventory today.\";\n  if (response.ok) {\n    const data: any = await response.json();\n    opportunity = data.content?.[0]?.text?.trim() || opportunity;\n  }\n\n  await prisma.kaiMorningBrief.create({\n    data: {\n      storeId, date: today,\n      revenueLastNight: revenueAmt,\n      ordersLastNight: overnightOrders,\n      topOpportunity: opportunity,\n      urgentAction: ctx.pendingOrders > 0 ? `${ctx.pendingOrders} orders need fulfilling` : undefined,\n    },\n  });\n\n  // Also create a pulse alert for morning brief\n  await createAlert(storeId,\n    \"morning_brief\",\n    `Good morning — here's your ${today} brief`,\n    `${overnightOrders > 0 ? `${overnightOrders} orders came in overnight (${sym}${revenueAmt.toLocaleString()}). ` : \"\"}${opportunity}`,\n    \"info\",\n    \"Give me my full morning brief for today\",\n    { date: today, orders: overnightOrders, revenue: revenueAmt }\n  );\n\n  return opportunity;\n}\n","backend/src/services/push.service.ts":"// src/services/push.service.ts\nimport webpush from \"web-push\";\nimport { prisma } from \"../config/database\";\n\n// VAPID keys — set these in .env\n// Generate with: npx web-push generate-vapid-keys\nconst VAPID_PUBLIC  = process.env.VAPID_PUBLIC_KEY  || \"\";\nconst VAPID_PRIVATE = process.env.VAPID_PRIVATE_KEY || \"\";\nconst VAPID_EMAIL   = process.env.VAPID_EMAIL       || \"mailto:push@dropos.io\";\n\nif (VAPID_PUBLIC && VAPID_PRIVATE) {\n  webpush.setVapidDetails(VAPID_EMAIL, VAPID_PUBLIC, VAPID_PRIVATE);\n}\n\n// ── Payload shapes ────────────────────────────────────────────────────────────\nexport interface PushPayload {\n  title:   string;\n  body:    string;\n  icon?:   string;\n  badge?:  string;\n  url?:    string;\n  tag?:    string;\n  image?:  string;\n  actions?: { action: string; title: string }[];\n}\n\n// ── Send to one subscription ──────────────────────────────────────────────────\nasync function sendToSubscription(sub: any, payload: PushPayload): Promise<boolean> {\n  try {\n    await webpush.sendNotification(\n      { endpoint: sub.endpoint, keys: { p256dh: sub.p256dh, auth: sub.auth } },\n      JSON.stringify(payload),\n      { TTL: 60 * 60 * 24 }  // 24h TTL\n    );\n    return true;\n  } catch (err: any) {\n    if (err.statusCode === 410 || err.statusCode === 404) {\n      // Subscription expired — remove it\n      await prisma.pushSubscription.updateMany({\n        where: { endpoint: sub.endpoint },\n        data:  { isActive: false },\n      });\n    }\n    return false;\n  }\n}\n\n// ── Send to all subscriptions for a user ─────────────────────────────────────\nexport async function pushToUser(userId: string, payload: PushPayload): Promise<number> {\n  if (!VAPID_PUBLIC || !VAPID_PRIVATE) return 0;\n\n  const subs = await prisma.pushSubscription.findMany({\n    where: { userId, isActive: true },\n  });\n\n  const results = await Promise.allSettled(\n    subs.map(s => sendToSubscription(s, payload))\n  );\n  return results.filter(r => r.status === \"fulfilled\" && r.value).length;\n}\n\n// ── Send to all store owner subs ──────────────────────────────────────────────\nexport async function pushToStoreOwner(storeId: string, payload: PushPayload): Promise<number> {\n  const store = await prisma.store.findUnique({ where: { id: storeId }, select: { userId: true } });\n  if (!store) return 0;\n  return pushToUser(store.ownerId, payload);\n}\n\n// ── Pre-built notification templates ────────────────────────────────────────\nexport const PushTemplates = {\n  newOrder: (orderRef: string, amount: string) => ({\n    title:   \"💰 New Order!\",\n    body:    `Order ${orderRef} — ${amount}`,\n    tag:     \"new-order\",\n    url:     \"/dashboard/orders\",\n    icon:    \"/icons/icon-192.png\",\n  }),\n\n  lowStock: (productName: string, qty: number) => ({\n    title:   \"⚠️ Low Stock Alert\",\n    body:    `${productName} has only ${qty} units left`,\n    tag:     \"low-stock\",\n    url:     \"/dashboard/inventory\",\n    icon:    \"/icons/icon-192.png\",\n  }),\n\n  abandonedCart: (count: number) => ({\n    title:   \"🛒 Abandoned Carts\",\n    body:    `${count} cart${count > 1 ? \"s\" : \"\"} abandoned in the last 24h — recover them now`,\n    tag:     \"abandoned-carts\",\n    url:     \"/dashboard/abandoned-carts\",\n    icon:    \"/icons/icon-192.png\",\n  }),\n\n  reviewReceived: (productName: string, rating: number) => ({\n    title:   `⭐ New ${rating}-star Review`,\n    body:    `Someone left a review on \"${productName}\"`,\n    tag:     \"review\",\n    url:     \"/dashboard/reviews\",\n    icon:    \"/icons/icon-192.png\",\n  }),\n\n  payoutReady: (amount: string) => ({\n    title:   \"💸 Payout Ready\",\n    body:    `${amount} commission payout is ready to be claimed`,\n    tag:     \"payout\",\n    url:     \"/dashboard/billing\",\n    icon:    \"/icons/icon-192.png\",\n  }),\n\n  flashSaleLive: (saleName: string) => ({\n    title:   \"🔥 Flash Sale Live\",\n    body:    `Your \"${saleName}\" flash sale has started — share it now!`,\n    tag:     \"flash-sale\",\n    url:     \"/dashboard/discounts\",\n    icon:    \"/icons/icon-192.png\",\n  }),\n\n  dailySummary: (revenue: string, orders: number) => ({\n    title:   \"📊 Today's Summary\",\n    body:    `${orders} orders · ${revenue} revenue`,\n    tag:     \"daily-summary\",\n    url:     \"/dashboard/analytics\",\n    icon:    \"/icons/icon-192.png\",\n  }),\n};\n"};
let n=0;
for(const [rel,content] of Object.entries(files)){
  const p=rel.replace(/\//g,path.sep);
  fs.mkdirSync(path.dirname(p),{recursive:true});
  fs.writeFileSync(p,content,'utf8');
  console.log('OK',rel.split('/').slice(-2).join('/'));n++;
}
console.log('Written:',n,'files');
try{
  execSync('git add .',{stdio:'inherit'});
  const st=execSync('git status --short',{encoding:'utf8'}).trim();
  if(st){
    execSync('git commit -m "fix: Add 10 missing Prisma models, fix field names, strict=false, compile to dist for Render OOM"',{stdio:'inherit'});
    execSync('git push origin main',{stdio:'inherit'});
    console.log('Pushed.');
  }else{console.log('Nothing new to commit');}
}catch(e){console.log('Git:',e.message);}
